import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.util.*;import java.math.*;import java.io.*;import java.nio.charset.StandardCharsets;class PublicExamplesTest{@Test void normalizationAndValueEquality(){Object a=TaskBinding.value(1,2),b=TaskBinding.value(2,4),c=TaskBinding.value(-2,-4);assertArrayEquals(new long[]{1,2},TaskBinding.parts(b));assertArrayEquals(new long[]{1,2},TaskBinding.parts(c));assertEquals(a,b);assertEquals(b,a);assertEquals(a,c);assertEquals(a.hashCode(),b.hashCode());assertNotEquals(a,null);assertArrayEquals(new long[]{0,1},TaskBinding.parts(TaskBinding.value(0,-3)));assertThrows(ArithmeticException.class,()->TaskBinding.value(1,0));}}
